package com.gymflow.product;
import com.gymflow.gym.Gym;import com.gymflow.category.Category;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="products",uniqueConstraints=@UniqueConstraint(name="uk_product_gym_sku",columnNames={"gym_id","sku"}),indexes=@Index(name="idx_product_gym_name",columnList="gym_id,name"))
public class Product{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="gym_id",nullable=false)private Gym gym;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="category_id")private Category category;@Column(nullable=false,length=40)private String sku;@Column(nullable=false,length=140)private String name;@Column(length=500)private String description;@Column(name="cost_price",nullable=false,precision=12,scale=2)private BigDecimal costPrice;@Column(name="sale_price",nullable=false,precision=12,scale=2)private BigDecimal salePrice;@Column(name="minimum_stock",nullable=false)private int minimumStock;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ProductStatus status=ProductStatus.ACTIVE;@Column(nullable=false,updatable=false)private Instant createdAt=Instant.now();protected Product(){}public Product(Gym gym,Category category,String sku,String name,String description,BigDecimal costPrice,BigDecimal salePrice,int minimumStock){this.gym=gym;this.category=category;this.sku=sku;this.name=name;this.description=description;this.costPrice=costPrice;this.salePrice=salePrice;this.minimumStock=minimumStock;}public UUID getId(){return id;}public Gym getGym(){return gym;}public Category getCategory(){return category;}public String getSku(){return sku;}public String getName(){return name;}public String getDescription(){return description;}public BigDecimal getCostPrice(){return costPrice;}public BigDecimal getSalePrice(){return salePrice;}public int getMinimumStock(){return minimumStock;}public ProductStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public void update(Category category,String sku,String name,String description,BigDecimal costPrice,BigDecimal salePrice,int minimumStock){this.category=category;this.sku=sku;this.name=name;this.description=description;this.costPrice=costPrice;this.salePrice=salePrice;this.minimumStock=minimumStock;}}
